    @_cuda.jit
    def _resample_cubic_cuda(src, row_coords, col_coords, out, nodata):
        """Catmull-Rom cubic resampling kernel (CUDA)."""
        i, j = _cuda.grid(2)
        h_out = out.shape[0]
