        wc0 = -0.5 * fc3 + fc2 - 0.5 * fc
        wc1 = 1.5 * fc3 - 2.5 * fc2 + 1.0
        wc2 = -1.5 * fc3 + 2.0 * fc2 + 0.5 * fc
        wc3 = 0.5 * fc3 - 0.5 * fc2

        # Catmull-Rom row weights
        fr2 = fr * fr
        fr3 = fr2 * fr
        wr0 = -0.5 * fr3 + fr2 - 0.5 * fr
        wr1 = 1.5 * fr3 - 2.5 * fr2 + 1.0
        wr2 = -1.5 * fr3 + 2.0 * fr2 + 0.5 * fr
        wr3 = 0.5 * fr3 - 0.5 * fr2

        val = 0.0
        has_nan = False

        # Row 0
        ric = r0 - 1
        if ric < 0:
            ric = 0
        elif ric >= sh:
            ric = sh - 1
        # Unrolled column loop for row 0
        cjc = c0 - 1
        if cjc < 0:
            cjc = 0
        elif cjc >= sw:
            cjc = sw - 1
        sv = src[ric, cjc]
        if sv != sv:
            has_nan = True
        if not has_nan:
            rv0 = sv * wc0
            cjc = c0
            if cjc < 0:
                cjc = 0
            elif cjc >= sw:
                cjc = sw - 1
            sv = src[ric, cjc]
            if sv != sv:
                has_nan = True
        if not has_nan:
            rv0 += sv * wc1
            cjc = c0 + 1
            if cjc < 0:
                cjc = 0
            elif cjc >= sw:
                cjc = sw - 1
            sv = src[ric, cjc]
            if sv != sv:
                has_nan = True
        if not has_nan:
            rv0 += sv * wc2
            cjc = c0 + 2
            if cjc < 0:
                cjc = 0
            elif cjc >= sw:
                cjc = sw - 1
            sv = src[ric, cjc]
            if sv != sv:
                has_nan = True
        if not has_nan:
            rv0 += sv * wc3
            val = rv0 * wr0

        # Row 1
        if not has_nan:
            ric = r0
            if ric < 0:
                ric = 0
            elif ric >= sh:
                ric = sh - 1
            cjc = c0 - 1
            if cjc < 0:
                cjc = 0
            elif cjc >= sw:
                cjc = sw - 1
            sv = src[ric, cjc]
            if sv != sv:
                has_nan = True
        if not has_nan:
            rv1 = sv * wc0
